 1| import { randomUUID } from 'node:crypto';
 2| import { paginate } from '../../lib/pagination.ts';
 3| import type { CreateProject, ListProjectsQuery, Project, ProjectPage, UpdateProject } from './schema.ts';
 4| 
 5| /** In-memory project store, ordered by creation time (ties broken by id). */
 6| const projects = new Map<string, Project>();
 7| 
 8| const sortKey = (project: Project): string => `${project.createdAt}|${project.id}`;
 9| 
10| export function listProjects(query: ListProjectsQuery): ProjectPage {
11|   return paginate([...projects.values()], query, sortKey);
12| }
13| 
14| export function getProject(id: string): Project | undefined {
15|   return projects.get(id);
16| }
17| 
18| export function createProject(input: CreateProject): Project {
19|   const now = new Date().toISOString();
20|   const project: Project = { id: randomUUID(), ...input, createdAt: now, updatedAt: now };
21|   projects.set(project.id, project);
22|   return project;
23| }
24| 
25| export function updateProject(id: string, patch: UpdateProject): Project | undefined {
26|   const current = projects.get(id);
27|   if (current === undefined) return undefined;
28|   const updated: Project = { ...current, ...patch, updatedAt: new Date().toISOString() };
29|   projects.set(id, updated);
30|   return updated;
31| }

