import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app.ts';
import { resetProjects } from '../src/modules/projects/store.ts';

const app = createApp();

beforeEach(() => {
  resetProjects();
});

afterEach(() => {
  resetProjects();
});

describe('projects API', () => {
  it('creates, lists, gets, updates, and deletes projects', async () => {
    const created = await request(app)
      .post('/v1/projects')
      .send({ name: 'Alpha', status: 'active' })
      .expect(201);

    expect(created.body).toMatchObject({
      name: 'Alpha',
      status: 'active',
    });
    expect(created.body).toHaveProperty('id');

    const projectId = created.body.id as string;

    await request(app)
      .get(`/v1/projects/${projectId}`)
      .expect(200)
      .expect(({ body }) => {
        expect(body).toMatchObject({ id: projectId, name: 'Alpha', status: 'active' });
      });

    await request(app)
      .patch(`/v1/projects/${projectId}`)
      .send({ name: 'Alpha Prime' })
      .expect(200)
      .expect(({ body }) => {
        expect(body).toMatchObject({ id: projectId, name: 'Alpha Prime', status: 'active' });
      });

    await request(app).delete(`/v1/projects/${projectId}`).expect(204).expect('');

    await request(app).get(`/v1/projects/${projectId}`).expect(404);
    await request(app).delete(`/v1/projects/${projectId}`).expect(404);
  });

  it('filters project lists by status while keeping cursor pagination', async () => {
    const projects = [
      { name: 'A', status: 'active' },
      { name: 'B', status: 'archived' },
      { name: 'C', status: 'active' },
      { name: 'D', status: 'archived' },
      { name: 'E', status: 'active' },
    ];

    for (const project of projects) {
      await request(app).post('/v1/projects').send(project).expect(201);
    }

    const archivedFirst = await request(app).get('/v1/projects?status=archived&limit=1').expect(200);
    expect(archivedFirst.body.data).toHaveLength(1);
    expect(archivedFirst.body.data[0].status).toBe('archived');
    expect(archivedFirst.body.nextCursor).toBeTruthy();

    const archivedSecond = await request(app)
      .get(`/v1/projects?status=archived&limit=1&cursor=${encodeURIComponent(archivedFirst.body.nextCursor)}`)
      .expect(200);
    expect(archivedSecond.body.data).toHaveLength(1);
    expect(archivedSecond.body.data[0].status).toBe('archived');

    const archivedIds = [...archivedFirst.body.data, ...archivedSecond.body.data].map((p) => p.id);
    expect(new Set(archivedIds).size).toBe(2);

    const activeAll = await request(app).get('/v1/projects?status=active&limit=10').expect(200);
    expect(activeAll.body.data.every((p: { status: string }) => p.status === 'active')).toBe(true);

    const allProjects = await request(app).get('/v1/projects?limit=10').expect(200);
    expect(allProjects.body.data).toHaveLength(5);
  });

  it('rejects malformed ids and unknown statuses', async () => {
    await request(app).get('/v1/projects?status=wrong').expect(422);
    await request(app).delete('/v1/projects/not-a-uuid').expect(422);
  });
});

