import { z } from 'zod';
import { CursorQuerySchema, pageSchema } from '../../lib/pagination.ts';

export const ProjectStatusSchema = z.enum(['active', 'archived']);

export const ProjectSchema = z.object({
  id: z.uuid(),
  name: z.string(),
  description: z.string().optional(),
  status: ProjectStatusSchema,
  createdAt: z.iso.datetime(),
  updatedAt: z.iso.datetime(),
});

export type Project = z.infer<typeof ProjectSchema>;

export const ProjectParamsSchema = z.object({ projectId: z.uuid() });

export const CreateProjectSchema = z.strictObject({
  name: z.string().trim().min(1),
  description: z.string().trim().min(1).optional(),
  status: ProjectStatusSchema.optional().default('active'),
});
export type CreateProject = z.infer<typeof CreateProjectSchema>;

export const UpdateProjectSchema = z
  .strictObject({
    name: z.string().trim().min(1).optional(),
    description: z.string().trim().min(1).optional().nullable(),
    status: ProjectStatusSchema.optional(),
  })
  .refine((value) => Object.keys(value).length > 0, { message: 'At least one field is required' });
export type UpdateProject = z.infer<typeof UpdateProjectSchema>;

export const ListProjectsQuerySchema = CursorQuerySchema.extend({
  status: ProjectStatusSchema.optional(),
});
export type ListProjectsQuery = z.infer<typeof ListProjectsQuerySchema>;

export const ProjectPageSchema = pageSchema(ProjectSchema);
export type ProjectPage = z.infer<typeof ProjectPageSchema>;

import { randomUUID } from 'node:crypto';
import request from 'supertest';
import type { Response } from 'supertest';
import { describe, expect, it } from 'vitest';
import { z } from 'zod';
import { createApp } from '../src/app.ts';
import { ProblemSchema } from '../src/lib/problem.ts';

const app = createApp();

const ProjectBody = z.strictObject({
  id: z.string().uuid(),
  name: z.string(),
  status: z.enum(['active', 'archived']),
  createdAt: z.string(),
});

const PageBody = z.strictObject({ data: z.array(ProjectBody), nextCursor: z.string().nullable() });

const UNKNOWN_ID = '00000000-0000-4000-8000-000000000000';

function expectProblem(res: Response, status: number) {
  expect(res.status).toBe(status);
  expect(res.type).toBe('application/problem+json');
  expect(() => ProblemSchema.parse(res.body)).not.toThrow();
}

async function createProject(body: Record<string, unknown> = {}) {
  return request(app).post('/v1/projects').send({ name: 'Project', status: 'active', ...body });
}

async function listAll(query: Record<string, string>) {
  const rows: Array<z.infer<typeof ProjectBody>> = [];
  let cursor: string | undefined;

  for (;;) {
    const res = await request(app)
      .get('/v1/projects')
      .query({ ...query, ...(cursor ? { cursor } : {}) });

    expect(res.status).toBe(200);
    const page = PageBody.parse(res.body);
    rows.push(...page.data);
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
  }

  return rows;
}

describe('POST /v1/projects', () => {
  it('creates a project', async () => {
    const res = await createProject();
    expect(res.status).toBe(201);
    const parsed = ProjectBody.parse(res.body);
    expect(parsed.name).toBe('Project');
    expect(parsed.status).toBe('active');
  });

  it('rejects an invalid body with problem json', async () => {
    const res = await request(app).post('/v1/projects').send({ name: '', status: 'paused' });
    expectProblem(res, 422);
  });
});

describe('GET /v1/projects', () => {
  it('lists projects with pagination', async () => {
    await createProject({ name: 'Alpha' });
    await createProject({ name: 'Beta' });
    const res = await request(app).get('/v1/projects').query({ limit: '1' });
    expect(res.status).toBe(200);
    const page = PageBody.parse(res.body);
    expect(page.data).toHaveLength(1);
    expect(page.nextCursor).toEqual(expect.any(String));
  });

  it('filters by status before paginating', async () => {
    const archived1 = await createProject({ name: 'Archived A', status: 'archived' });
    await createProject({ name: 'Active A', status: 'active' });
    const archived2 = await createProject({ name: 'Archived B', status: 'archived' });
    await createProject({ name: 'Active B', status: 'active' });

    const archivedRows = await listAll({ status: 'archived', limit: '1' });
    expect(archivedRows.map((project) => project.id).sort()).toEqual(
      [archived1.body.id, archived2.body.id].sort(),
    );
    expect(archivedRows.every((project) => project.status === 'archived')).toBe(true);

    const activeRows = await listAll({ status: 'active', limit: '1' });
    expect(activeRows.every((project) => project.status === 'active')).toBe(true);
  });

  it('rejects unknown status with problem json', async () => {
    const res = await request(app).get('/v1/projects').query({ status: 'paused' });
    expectProblem(res, 422);
  });
});

describe('GET /v1/projects/:projectId', () => {
  it('returns a project', async () => {
    const created = await createProject({ name: 'Fetchable' });
    const res = await request(app).get(`/v1/projects/${created.body.id}`);
    expect(res.status).toBe(200);
    expect(ProjectBody.parse(res.body).id).toBe(created.body.id);
  });

  it('returns 404 for a missing project', async () => {
    const res = await request(app).get(`/v1/projects/${UNKNOWN_ID}`);
    expectProblem(res, 404);
  });
});

describe('DELETE /v1/projects/:projectId', () => {
  it('deletes a project and returns 204', async () => {
    const created = await createProject({ name: 'Delete me' });
    const res = await request(app).delete(`/v1/projects/${created.body.id}`);
    expect(res.status).toBe(204);
    expect(res.text).toBe('');

    const after = await request(app).get(`/v1/projects/${created.body.id}`);
    expectProblem(after, 404);
  });

  it('returns 404 for a missing project', async () => {
    const res = await request(app).delete(`/v1/projects/${UNKNOWN_ID}`);
    expectProblem(res, 404);
  });

  it('returns 422 for a malformed id', async () => {
    const res = await request(app).delete('/v1/projects/not-a-uuid');
    expectProblem(res, 422);
  });
});

describe('PATCH /v1/projects/:projectId', () => {
  it('updates a project', async () => {
    const created = await createProject({ name: 'Before' });
    const res = await request(app).patch(`/v1/projects/${created.body.id}`).send({ name: 'After' });
    expect(res.status).toBe(200);
    expect(ProjectBody.parse(res.body).name).toBe('After');
  });
});

