import { z } from 'zod';
import { CursorQuerySchema, pageSchema } from '../../lib/pagination.ts';

export const ProjectStatusSchema = z.enum(['active', 'archived']);

export const ProjectSchema = z.object({
  id: z.uuid(),
  name: z.string().min(1),
  status: ProjectStatusSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});

export type Project = z.infer<typeof ProjectSchema>;

export const ProjectParamsSchema = z.object({ projectId: z.uuid() });

export const CreateProjectSchema = z.strictObject({
  name: z.string().min(1),
  status: ProjectStatusSchema,
});
export type CreateProject = z.infer<typeof CreateProjectSchema>;

export const UpdateProjectSchema = z
  .strictObject({
    name: z.string().min(1).optional(),
    status: ProjectStatusSchema.optional(),
  })
  .refine((value) => value.name !== undefined || value.status !== undefined, { message: 'at least one field required' });
export type UpdateProject = z.infer<typeof UpdateProjectSchema>;

export const ListProjectsQuerySchema = CursorQuerySchema.extend({
  status: ProjectStatusSchema.optional(),
});
export type ListProjectsQuery = z.infer<typeof ListProjectsQuerySchema>;

export const ProjectPageSchema = pageSchema(ProjectSchema);
export type ProjectPage = z.infer<typeof ProjectPageSchema>;

